      a {
        color: var(--color-primary);
      }

      a:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: var(--radius-sm);
        background: var(--color-surface);
        padding: 0.7rem 1rem;
        box-shadow: var(--shadow-soft);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 1.25rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.7rem;
        min-width: 0;
        color: var(--color-text);
        font-size: 1.05rem;
        font-weight: 800;
        letter-spacing: -0.02em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.3rem;
        height: 2.3rem;
        flex: 0 0 auto;
        place-items: center;
        border-radius: 0.8rem;
        background: var(--color-text);
        color: var(--color-surface);
      }

      .header-link {
        border-radius: 999px;
        color: var(--color-muted);
        font-weight: 700;
        text-decoration: none;
      }

      main {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 2rem 0 4rem;
      }

      .preview-layout {
        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(17rem, 0.65fr);
        gap: 1.5rem;
        align-items: stretch;
      }

      .image-card,
      .details-card {
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .image-card {
        overflow: hidden;
      }

      .image-frame {
        display: grid;
        min-height: 24rem;
        place-items: center;
        background:
          linear-gradient(135deg, #0f172a, #1d4ed8 62%, #f8fafc 62%, #e2e8f0);
      }

      .image-frame img {
        width: min(78%, 36rem);
        max-width: 100%;
        height: auto;
        border: 10px solid var(--color-surface);
        border-radius: 24px;
        box-shadow: 0 26px 80px #111827;
        object-fit: cover;
      }

      .image-caption {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 1.15rem;
      }

      .badge {
        border-radius: 999px;
        background: var(--color-surface-muted);
        color: var(--color-muted);
        padding: 0.35rem 0.7rem;
        font-size: 0.86rem;
        font-weight: 800;
      }

      .details-card {
        display: flex;
        flex-direction: column;
        gap: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .eyebrow {
        margin: 0 0 0.55rem;
        color: var(--color-primary);
        font-size: 0.84rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        overflow-wrap: anywhere;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 4.3rem);
        line-height: 0.96;
        letter-spacing: -0.07em;
      }

      h2 {
        margin: 0;
        font-size: 1.35rem;
        line-height: 1.2;
        letter-spacing: -0.03em;
      }

      p {
        margin: 0;
        color: var(--color-muted);
      }

      .metadata {
        display: grid;
        gap: 0.85rem;
        margin: 0;
      }

      .metadata div {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--color-border);
        padding-bottom: 0.75rem;
      }

      .metadata dt {
        color: var(--color-muted);
        font-weight: 700;
      }

      .metadata dd {
        margin: 0;
        color: var(--color-text);
        font-weight: 800;
        text-align: right;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-top: auto;
      }

      button {
        min-height: 2.85rem;
        border: 1px solid transparent;
        border-radius: var(--radius-sm);
        padding: 0.75rem 1rem;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
      }

      .button-secondary {
        border-color: var(--color-border);
        background: var(--color-surface);
        color: var(--color-text);
      }

      .button-secondary:hover {
        background: var(--color-surface-muted);
      }

      .button-danger {
        background: var(--color-danger);
        color: var(--color-surface);
      }

      .button-danger:hover {
        background: var(--color-danger-hover);
      }

      .trigger {
        width: 100%;
      }

      dialog {
        width: min(31rem, calc(100% - 2rem));
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        padding: 0;
        background: var(--color-surface);
        color: var(--color-text);
        box-shadow: 0 30px 90px #344054;
      }

      dialog::backdrop {
        background: #101828;
      }

      .dialog-panel {
        display: grid;
        gap: 1.1rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3.2rem;
        height: 3.2rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee4e2;
        color: var(--color-danger);
      }

      .dialog-icon svg {
        width: 1.65rem;
        height: 1.65rem;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        padding-top: 0.35rem;
      }

      .dialog-actions button {
        flex: 1 1 10rem;
      }

      .status-message {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--color-danger);
        font-weight: 800;
      }

      @media (max-width: 760px) {
        .site-header {
          align-items: flex-start;
          flex-direction: column;
        }

        .preview-layout {
          grid-template-columns: 1fr;
        }

        .image-frame {
          min-height: 18rem;
        }

        .image-caption,
        .metadata div {
          align-items: flex-start;
          flex-direction: column;
          gap: 0.35rem;
        }

        .metadata dd {
          text-align: left;
        }
      }

      @media (prefers-reduced-motion: no-preference) {
        .skip-link,
        button {
          transition: background-color 160ms ease, color 160ms ease, transform 160ms ease;
        }

        button:active {
          transform: translateY(1px);
        }
      }

      @media (forced-colors: active) {
        :root {
          --color-page: Canvas;
          --color-surface: Canvas;
          --color-surface-muted: Canvas;
          --color-text: CanvasText;
          --color-muted: CanvasText;
          --color-primary: LinkText;
          --color-primary-hover: LinkText;
          --color-danger: ButtonText;
          --color-danger-hover: ButtonText;
          --color-border: ButtonBorder;
          --color-focus: Highlight;
        }

        .brand-mark,
        .button-danger,
        .dialog-icon {
          border: 1px solid ButtonBorder;
          background: ButtonFace;
          color: ButtonText;
        }

        dialog::backdrop {
          background: Canvas;
        }
      }
