  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header class="site-header">
      <a class="brand" href="#" aria-label="Lumina library home">
        <span class="brand-mark" aria-hidden="true">L</span>
        <span>Lumina Library</span>
      </a>
      <a class="header-link" href="#">Back to library</a>
    </header>

    <main id="main-content">
      <section class="preview-layout" aria-labelledby="page-title">
        <article class="image-card">
          <div class="image-frame">
            <img
              src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
              alt="Sunlit mountain cabin beside a lake at sunrise"
            >
          </div>
          <div class="image-caption">
            <p>Sunlit mountain cabin beside a lake at sunrise.</p>
            <span class="badge">Image preview</span>
          </div>
        </article>

        <aside class="details-card" aria-labelledby="details-heading">
          <div>
            <p class="eyebrow">Image details</p>
            <h1 id="page-title">Mountain retreat</h1>
          </div>

          <div>
            <h2 id="details-heading">Library information</h2>
            <p>Review this saved image before managing it in your library.</p>
          </div>

          <dl class="metadata">
            <div>
              <dt>Collection</dt>
              <dd>Travel ideas</dd>
            </div>
            <div>
              <dt>Added</dt>
              <dd>May 6, 2026</dd>
            </div>
            <div>
              <dt>Format</dt>
              <dd>JPEG</dd>
            </div>
          </dl>

          <div>
            <div class="actions">
              <button class="button-danger trigger" type="button" aria-haspopup="dialog">
                Delete image
              </button>
            </div>
            <p class="status-message" id="delete-status" aria-live="polite"></p>
          </div>
        </aside>
      </section>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <div class="dialog-panel">
        <div class="dialog-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" focusable="false">
            <path
              fill="currentColor"
              d="M9 3h6a1 1 0 0 1 1 1v1h4v2h-1.1l-.82 12.29A3 3 0 0 1 15.08 22H8.92a3 3 0 0 1-2.99-2.71L5.1 7H4V5h4V4a1 1 0 0 1 1-1Zm5 2h-4v0h4v0ZM7.11 7l.81 12.16a1 1 0 0 0 1 .84h6.16a1 1 0 0 0 1-.84L16.89 7H7.11ZM10 9h2v9h-2V9Zm4 0h2v9h-2V9Z"
            />
          </svg>
        </div>

        <div>
          <h2 id="dialog-title">Delete image?</h2>
          <p id="dialog-description">
            This will remove "Mountain retreat" from your library. This action cannot be undone.
          </p>
        </div>

        <div class="dialog-actions">
          <button class="button-secondary" type="button" data-close-dialog>
            Cancel
          </button>
          <button class="button-danger" type="button" id="confirm-delete">
            Delete image
          </button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.querySelector("#delete-dialog");
      const openButton = document.querySelector(".trigger");
      const closeButton = document.querySelector("[data-close-dialog]");
      const confirmButton = document.querySelector("#confirm-delete");
      const statusMessage = document.querySelector("#delete-status");

      openButton.addEventListener("click", () => {
        dialog.showModal();
      });

      closeButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "delete") {
          statusMessage.textContent = "Image deleted from your library.";
        }
      });
    </script>
  </body>
