        color: var(--color-muted);
        padding: 0.35rem 0.7rem;
        font-size: 0.86rem;
        font-weight: 800;
      }

      .details-card {
        display: flex;
        flex-direction: column;
        gap: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .eyebrow {
        margin: 0 0 0.55rem;
        color: var(--color-primary);
        font-size: 0.84rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        overflow-wrap: anywhere;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 4.3rem);
        line-height: 0.96;
        letter-spacing: -0.07em;
      }

      h2 {
        margin: 0;
        font-size: 1.35rem;
        line-height: 1.2;
        letter-spacing: -0.03em;
      }

      p {
        margin: 0;
        color: var(--color-muted);
      }

      .metadata {
        display: grid;
        gap: 0.85rem;
        margin: 0;
      }

      .metadata div {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--color-border);
        padding-bottom: 0.75rem;
      }

      .metadata dt {
        color: var(--color-muted);
        font-weight: 700;
      }

      .metadata dd {
        margin: 0;
        color: var(--color-text);
        font-weight: 800;
        text-align: right;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-top: auto;
      }

      button {
        min-height: 2.85rem;
        border: 1px solid transparent;
        border-radius: var(--radius-sm);
        padding: 0.75rem 1rem;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
      }

      .button-secondary {
        border-color: var(--color-border);
        background: var(--color-surface);
        color: var(--color-text);
      }

      .button-secondary:hover {
        background: var(--color-surface-muted);
      }

      .button-danger {
        background: var(--color-danger);
        color: var(--color-surface);
      }

      .button-danger:hover {
        background: var(--color-danger-hover);
      }

      .trigger {
        width: 100%;
      }

      dialog {
        width: min(31rem, calc(100% - 2rem));
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        padding: 0;
        background: var(--color-surface);
        color: var(--color-text);
        box-shadow: 0 30px 90px #344054;
      }

      dialog::backdrop {
        background: #101828;
      }

      .dialog-panel {
        display: grid;
        gap: 1.1rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3.2rem;
        height: 3.2rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee4e2;
        color: var(--color-danger);
      }

      .dialog-icon svg {
        width: 1.65rem;
        height: 1.65rem;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        padding-top: 0.35rem;
      }

      .dialog-actions button {
        flex: 1 1 10rem;
      }

      .status-message {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--color-danger);
        font-weight: 800;
