+            <span class="badge">Image preview</span>
+          </div>
+        </article>
+
+        <aside class="details-card" aria-labelledby="details-heading">
+          <div>
+            <p class="eyebrow">Image details</p>
+            <h1 id="page-title">Mountain retreat</h1>
+          </div>
+
+          <div>
+            <h2 id="details-heading">Library information</h2>
+            <p>Review this saved image before managing it in your library.</p>
+          </div>
+
+          <dl class="metadata">
+            <div>
+              <dt>Collection</dt>
+              <dd>Travel ideas</dd>
+            </div>
+            <div>
+              <dt>Added</dt>
+              <dd>May 6, 2026</dd>
+            </div>
+            <div>
+              <dt>Format</dt>
+              <dd>JPEG</dd>
+            </div>
+          </dl>
+
+          <div>
